package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var DateRecVar DateRec

var dateFileReader *bufio.Reader
var dateFile *os.File

func formatP9(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	// low-order digits, handle negative? not needed but keep
	uv := v % mod
	if uv < 0 {
		uv += mod
	}
	s := strconv.FormatInt(uv, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func parseP9(s string, width int) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// Keep only digits? Input should be digits; but handle
	// If shorter, it's already padded; we trimmed.
	// Parse integer
	// For implied decimal not needed here
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// if contains spaces or non-digits, try extract digits
		filtered := ""
		for _, c := range s {
			if c >= '0' && c <= '9' {
				filtered += string(c)
			}
		}
		if filtered == "" {
			return 0
		}
		v, _ = strconv.ParseInt(filtered, 10, 64)
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

var _ = decimal.NewFromInt

func MAINPARA() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// If file not found, treat as empty
		dateFile = nil
		dateFileReader = bufio.NewReader(strings.NewReader(""))
	} else {
		dateFileReader = bufio.NewReader(dateFile)
	}
	READPARA()
	for !(WsEofFlag == "Y") {
		PROCESSPARA()
	}
	if dateFile != nil {
		dateFile.Close()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Printf("%s%s%s%s%s%s\n", "VALID: ", formatP9(WsValid, 2), " BAD MONTH: ", formatP9(WsBadMonth, 2), " BAD DAY: ", formatP9(WsBadDay, 2))
}

func READPARA() {
	line, err := dateFileReader.ReadString('\n')
	if err != nil {
		// EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// last line without newline, process it
	}
	// Remove trailing newline characters \r\n
	if strings.HasSuffix(line, "\n") {
		line = strings.TrimSuffix(line, "\n")
		line = strings.TrimSuffix(line, "\r")
	}
	// Pad with spaces to record length 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	// If we had EOF with no data, the above would have returned; but handle
	if line == "" && err != nil {
		WsEofFlag = "Y"
		return
	}
	// Parse fields
	rawId := line[0:4]
	rawYyyy := line[4:8]
	rawMm := line[8:10]
	rawDd := line[10:12]

	DateRecVar.DtId = rawId
	DateRecVar.DtYyyy = parseP9(rawYyyy, 4)
	DateRecVar.DtMm = parseP9(rawMm, 2)
	DateRecVar.DtDd = parseP9(rawDd, 2)

	if err != nil && len(line) == 0 {
		WsEofFlag = "Y"
		return
	}
	// Detect true EOF after this read: we already consumed line. Next read will be EOF.
	// But COBOL sets INPUT-DONE only on AT END (when read fails to get a record)
	// Our logic: we set EOF flag only when ReadString returns error and no data.
	// So we should not set flag now if we successfully got a line even if err==io.EOF.
	// Need to peek? We set flag only when no data.
	if err != nil {
		// We have processed the last line; next READ will hit EOF.
		// We need to keep flag N for now; but we need to know EOF on next call.
		// We'll handle by setting a pending EOF? Easier: if err != nil, we consumed last line,
		// we should leave flag N now, but the next READ will return EOF.
		// However ReadString with io.EOF still returns line content; we processed it.
		// So do not set flag.
	}
	// To properly emulate, we need to detect EOF on next read, not now.
	// But if file ended exactly at newline, the next ReadString will return "", io.EOF and we will set flag then.
}

func PROCESSPARA() {
	LEAPPARA()
	if DateRecVar.DtMm < 1 || DateRecVar.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		fmt.Printf("%s%s%s\n", DateRecVar.DtId, " BAD MONTH ", formatP9(DateRecVar.DtMm, 2))
	} else {
		DAYSPARA()
		if DateRecVar.DtDd < 1 || DateRecVar.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Printf("%s%s%s%s%s\n", DateRecVar.DtId, " BAD DAY ", formatP9(DateRecVar.DtDd, 2), " MAX ", formatP9(WsMaxDay, 2))
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Printf("%s%s%s%s%s%s%s\n", DateRecVar.DtId, " VALID ", formatP9(DateRecVar.DtYyyy, 4), "-", formatP9(DateRecVar.DtMm, 2), "-", formatP9(DateRecVar.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = DateRecVar.DtYyyy / 4
	WsR4 = DateRecVar.DtYyyy % 4
	WsQ = DateRecVar.DtYyyy / 100
	WsR100 = DateRecVar.DtYyyy % 100
	WsQ = DateRecVar.DtYyyy / 400
	WsR400 = DateRecVar.DtYyyy % 400
	// truncation to PIC 9(4)/9(3) low-order digits
	WsQ = WsQ % 10000
	WsR4 = WsR4 % 1000
	WsR100 = WsR100 % 1000
	WsR400 = WsR400 % 1000
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch DateRecVar.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = WsMaxDay % 100
}

func main() {
	MAINPARA()
}
